2|import { writable } from 'svelte/store';
3|
4|function createAuthStore() {
5|  const { subscribe, set, update } = writable({
6|    user: null,
7|    loading: true,
8|    isLoggedIn: false
9|  });
10|
11|  return {
12|    subscribe,
13|    async checkAuth() {
14|      try {
15|        const res = await fetch('/api/auth/me');
16|        if (res.ok) {
17|          const data = await res.json();
18|          if (data.success) {
19|            set({ user: data.data, loading: false, isLoggedIn: true });
20|            return;
21|          }
22|        }
23|        set({ user: null, loading: false, isLoggedIn: false });
24|      } catch {
25|        set({ user: null, loading: false, isLoggedIn: false });
26|      }
27|    },
28|    setUser(user) {
29|      update(s => ({ ...s, user, isLoggedIn: !!user }));
30|    },
31|    logout() {
32|      set({ user: null, loading: false, isLoggedIn: false });
33|    }
34|  };
35|}
36|
37|export const auth = createAuthStore();
