1|// Toast store
2|import { writable } from 'svelte/store';
3|
4|let id = 0;
5|
6|function createToastStore() {
7|  const { subscribe, update } = writable([]);
8|
9|  return {
10|    subscribe,
11|    show(message, type = 'success') {
12|      const toast = { id: ++id, message, type };
13|      update(toasts => [...toasts, toast]);
14|      setTimeout(() => {
15|        update(toasts => toasts.filter(t => t.id !== toast.id));
16|      }, 3000);
17|    },
18|    success(msg) { this.show(msg, 'success'); },
19|    error(msg) { this.show(msg, 'danger'); },
20|    warning(msg) { this.show(msg, 'warning'); }
21|  };
22|}
23|
24|export const toasts = createToastStore();
